SELECT d.Matricola, d.Cognome, d.Nome
FROM Docente d
WHERE d.Matricola IN (
  SELECT c.Docente FROM Corso c
  WHERE c.CFU > (SELECT AVG(CFU) FROM Corso)
);

SELECT DISTINCT d.Matricola, d.Cognome, d.Nome
FROM Docente d JOIN Corso c ON c.Docente = d.Matricola
WHERE c.CFU > (SELECT AVG(CFU) FROM Corso);

SELECT d.Matricola, d.Cognome, d.Nome
FROM Docente d
WHERE NOT EXISTS (
  SELECT * FROM Corso c WHERE c.Docente = d.Matricola
);

SELECT d.Matricola, d.Cognome, d.Nome
FROM Docente d
WHERE d.Matricola NOT IN (
  SELECT c.Docente FROM Corso c WHERE c.Docente IS NOT NULL
);

SELECT s.Matricola, s.Cognome, s.Nome
FROM Studente s
WHERE NOT EXISTS (
  SELECT * FROM Corso c
  WHERE c.CorsoDiLaurea = s.CorsoDiLaurea AND c.Anno = 1
    AND NOT EXISTS (
      SELECT * FROM Esame e
      WHERE e.Studente = s.Matricola AND e.Corso = c.Codice
    )
);

SELECT s.Matricola, s.Cognome, s.Nome
FROM Studente s
WHERE (
  SELECT COUNT(*) FROM Corso c
  WHERE c.CorsoDiLaurea = s.CorsoDiLaurea AND c.Anno = 1
) = (
  SELECT COUNT(*) FROM Esame e JOIN Corso c ON c.Codice = e.Corso
  WHERE e.Studente = s.Matricola AND c.CorsoDiLaurea = s.CorsoDiLaurea AND c.Anno = 1
);

SELECT c.Codice, c.Nome, c.CFU
FROM Corso c
WHERE c.CFU > ALL (
  SELECT CFU FROM Corso WHERE Anno = 2
);

SELECT c.Codice, c.Nome, c.CFU
FROM Corso c
WHERE NOT EXISTS (
  SELECT * FROM Corso c2
  WHERE c2.Anno = 2 AND c2.CFU >= c.CFU
);
